    out["membership"] = {
        k: membership.get(k)
        for k in (
            "source",
            "universe_status",
            "fresh",
            "degraded",
            "cap_reached",
            "refresh_incomplete",
            "resolved_at",
        )
    }
    for horizon in ("day", "hour"):
        block = coverage.get(horizon) if isinstance(coverage.get(horizon), dict) else {}
        slim: Dict[str, Any] = {
            "attempted": block.get("attempted"),
            "succeeded_count": len(block.get("succeeded") or []),
