def _publish_wall_gauge_value(timing: Dict[str, Any]) -> float:
    from internal.metrics import SCORE_SNAPSHOT_TIMING_PUBLISH_UNAVAILABLE

    on_wire = timing.get("publish_wall_seconds")
    if on_wire is not None:
