    try:
        from internal.metrics import (
            SCORE_SNAPSHOT_COVERAGE_COMPLETE,
            SCORE_SNAPSHOT_COVERAGE_PUBLISHED,
            SCORE_SNAPSHOT_TIMING_BUILD_SECONDS,
            SCORE_SNAPSHOT_TIMING_PUBLISH_SECONDS,
        )
    except Exception:
        return
    timing = coverage.get("timing") or {}

