def publish_metrics(coverage: Dict[str, Any]) -> None:
    try:
        from internal.metrics import (
            SCORE_SNAPSHOT_COVERAGE_COMPLETE,
            SCORE_SNAPSHOT_COVERAGE_PUBLISHED,
