            "skipped_invalid": block.get("skipped_invalid"),
            "complete": block.get("complete"),
        }
        if horizon == "hour":
            slim["hour_copied_from_day"] = block.get("hour_copied_from_day")
            slim["status"] = block.get("status")
        out[horizon] = slim
    return out


